std::string source_locale(std::string_view source, std::string_view fallback) {
    if (source.starts_with("\xef\xbb\xbf")) source.remove_prefix(3);
    const auto end = source.find('\n'); source = source.substr(0, end);
    while (!source.empty() && (source.front() == ' ' || source.front() == '\t')) source.remove_prefix(1);
    if (source.starts_with("#no") || source.starts_with("#en")) {
        auto rest = source.substr(3);
        while (!rest.empty() && (rest.front() == ' ' || rest.front() == '\t' || rest.front() == '\r')) rest.remove_prefix(1);
        if (rest.empty() || rest.starts_with("//")) return std::string(source.substr(1, 2));
    }
    return fallback == "no" ? "no" : "en";
}
